// @zeus-internal
import { ArtemisWordEntrance } from "../../../../lib/word-entrance";
export interface TextRevealProps { text: string | string[]; as?: "span" | "div" | "p" | "h1" | "h2" | "h3" | "h4"; className?: string; stagger?: number; delay?: number; blur?: number; yOffset?: string | number; amount?: number; whileInView?: boolean; }
export function TextReveal({text, as: Tag = "span", className, stagger = 0.06, delay, blur, yOffset = "24%", amount, whileInView = true}: TextRevealProps) { return <Tag className={className}><ArtemisWordEntrance words={Array.isArray(text) ? text : text.split(/\s+/)} stagger={stagger} delay={delay} blur={blur} yOffset={typeof yOffset === "number" ? yOffset + "px" : yOffset} amount={amount} entered={whileInView ? undefined : true}/></Tag>; }

